pub fn session_search_view_in(
    directory: &std::path::Path,
    query: &str,
) -> Result<serde_json::Value, String> {
    let hits =
        crate::session::search_sessions(directory, query, 32).map_err(|error| error.to_string())?;
    Ok(json!({
        "command": "session",
        "route": "local",
        "accepted": true,
        "action": "search",
        "query": query,
        "count": hits.len(),
        "matches": hits.iter().map(|hit| json!({
            "session": serialized_session_summary(&hit.summary),
            "matches": hit.matches,
            "snippets": hit.snippets,
        })).collect::<Vec<_>>(),
    }))
}

